/* ---------- CSS Custom Properties ---------- */
:root,
[data-theme="light"] {
  /* Core palette — Studio Precision 2026 (Light Mode Default) */
  --clr-primary:       #1d4ed8;
  --clr-primary-dark:  #1e40af;
  --clr-primary-light: #eff6ff;
  --clr-primary-glow:  rgba(29, 78, 216, 0.20);
  --clr-secondary:     #0d9488;
  --clr-accent:        #10b981;
  --clr-accent-light:  #d1fae5;
  --clr-warning:       #f59e0b;
  --clr-warning-light: #fef3c7;
  --clr-error:         #ef4444;
  --clr-error-light:   #fee2e2;
  --clr-success:       #10b981;
  --clr-success-light: #d1fae5;

  /* Surfaces & Containers (Studio Precision Light) */
  --clr-bg:            #f8fafd;
  --clr-surface:       #ffffff;
  --clr-surface-low:   #ffffff;
  --clr-surface-container: #f1f5f9;
  --clr-surface-high:  #e2e8f0;
  --clr-surface-highest: #cbd5e1;
  --clr-surface-alt:   #edf2f8;
  --clr-border:        #e2e8f0;
  --clr-border-strong: #cbd5e1;
  --clr-border-subtle: #f1f5f9;
  --clr-text:          #0f172a;
  --clr-text-secondary:#334155;
  --clr-text-muted:    #64748b;
  --clr-text-disabled: #94a3b8;

  /* Material / Wizard variables mapping (Light) */
  --md-surface-container: var(--clr-surface-container);
  --md-surface-variant: var(--clr-surface-alt);
  --md-outline: var(--clr-border);
  --md-text-primary: var(--clr-text);
  --md-text-secondary: var(--clr-text-secondary);
  --md-primary: var(--clr-primary);
  --md-primary-container: var(--clr-primary-light);

  /* Question Type Distinct Accents */
  --qtype-mc-bg:       rgba(37, 99, 235, 0.12);
  --qtype-mc-clr:      #1d4ed8;
  --qtype-mc-border:   rgba(37, 99, 235, 0.35);

  --qtype-tf-bg:       rgba(13, 148, 136, 0.12);
  --qtype-tf-clr:      #0d9488;
  --qtype-tf-border:   rgba(13, 148, 136, 0.35);

  --qtype-fib-bg:      rgba(147, 51, 234, 0.12);
  --qtype-fib-clr:     #7e22ce;
  --qtype-fib-border:  rgba(147, 51, 234, 0.35);

  --qtype-mr-bg:       rgba(217, 119, 6, 0.12);
  --qtype-mr-clr:      #b45309;
  --qtype-mr-border:   rgba(217, 119, 6, 0.35);

  --qtype-match-bg:    rgba(225, 29, 72, 0.12);
  --qtype-match-clr:   #be123c;
  --qtype-match-border:rgba(225, 29, 72, 0.35);

  /* CEFR level colors — Studio High-Precision */
  --cefr-a0:   #94a3b8;
  --cefr-a1:   #14b8a6;
  --cefr-a1p:  #0d9488;
  --cefr-a2:   #3b82f6;
  --cefr-a2p:  #2563eb;
  --cefr-b1:   #8b5cf6;
  --cefr-b1p:  #7c3aed;
  --cefr-b2:   #1d4ed8;
  --cefr-b2p:  #1e3a8a;
  --cefr-c1:   #047857;

  /* Typography */
  --font-headline: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-body:     'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono:     'JetBrains Mono', 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;

  /* Type scale */
  --text-xs:   11px;
  --text-sm:   13px;
  --text-base: 15px;
  --text-md:   16px;
  --text-lg:   18px;
  --text-xl:   22px;
  --text-2xl:  26px;
  --text-3xl:  32px;
  --text-4xl:  40px;

  /* Spacing */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 20px;
  --sp-6: 24px;
  --sp-8: 32px;
  --sp-10: 40px;
  --sp-12: 48px;

  /* Radii */
  --radius-xs:  3px;
  --radius-sm:  5px;
  --radius:     8px;
  --radius-md:  10px;
  --radius-lg:  14px;
  --radius-xl:  18px;
  --radius-full: 9999px;

  /* Elevation Shadows */
  --shadow-xs: 0 1px 2px rgba(15, 23, 42, 0.05);
  --shadow-sm: 0 1px 3px rgba(15, 23, 42, 0.08), 0 1px 2px rgba(15, 23, 42, 0.04);
  --shadow:    0 4px 6px -1px rgba(15, 23, 42, 0.07), 0 2px 4px -2px rgba(15, 23, 42, 0.04);
  --shadow-md: 0 10px 15px -3px rgba(15, 23, 42, 0.08), 0 4px 6px -4px rgba(15, 23, 42, 0.03);
  --shadow-lg: 0 20px 25px -5px rgba(15, 23, 42, 0.08), 0 8px 10px -6px rgba(15, 23, 42, 0.03);

  /* Transitions */
  --transition-fast: 120ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition:      180ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 300ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Layout dimensions */
  --topbar-h: 56px;
  --header-h: 56px;
  --sidebar-w: 280px;
  --footer-h: 50px;
}

/* ---------- Themes (Color Schemes) ---------- */
[data-theme="navy_standard"], body.theme-navy_standard {
  --clr-primary:       #1B4F8A;
  --clr-primary-dark:  #143D6E;
  --clr-primary-light: #D6E4F7;
  --clr-secondary:     #3A7CA5;
  --clr-bg:            #F6F8FC;
  --clr-surface:       #FFFFFF;
  --clr-surface-alt:   #EDF2F8;
  --clr-border:        #DDE5EF;
  --clr-text:          #1A2332;
}

[data-theme="light_academic"], body.theme-light_academic {
  --clr-primary:       #1F6E6C;
  --clr-primary-dark:  #154D4B;
  --clr-primary-light: #D8EEEE;
  --clr-secondary:     #355C6E;
  --clr-accent:        #C67C3E;
  --clr-bg:            #F8F7F0;
  --clr-surface:       #FFFFFF;
  --clr-surface-alt:   #EDE9DC;
  --clr-border:        #E2DDD0;
  --clr-border-strong: #BDB7A4;
  --clr-text:          #1C2B2E;
  --clr-text-secondary:#3C4D50;
}

[data-theme="dark_mode"], body.theme-dark_mode {
  --clr-primary:       #3B82F6;
  --clr-primary-dark:  #2563EB;
  --clr-primary-light: #1E293B;
  --clr-secondary:     #60A5FA;
  --clr-accent:        #10B981;
  --clr-bg:            #0B1120;
  --clr-surface:       #1E293B;
  --clr-surface-alt:   #334155;
  --clr-border:        #334155;
  --clr-border-strong: #475569;
  --clr-text:          #F8FAFC;
  --clr-text-secondary:#CBD5E1;
  --clr-text-muted:    #94A3B8;
  --clr-text-disabled: #64748B;
  --shadow-xs: 0 1px 2px rgba(0,0,0,0.3);
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
  --shadow:    0 4px 6px rgba(0,0,0,0.4);
  --shadow-md: 0 10px 15px rgba(0,0,0,0.5);
  --shadow-lg: 0 20px 25px rgba(0,0,0,0.6);
}

/* ---------- Reset & Base ---------- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  color: var(--clr-text);
  background: var(--clr-bg);
  line-height: 1.6;
}

/* ---------- Typography ---------- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-headline);
  font-weight: 700;
  line-height: 1.25;
  color: var(--clr-text);
}

h1 { font-size: var(--text-3xl); }
h2 { font-size: var(--text-2xl); }
h3 { font-size: var(--text-xl); }
h4 { font-size: var(--text-lg); }
h5 { font-size: var(--text-base); font-weight: 600; }
h6 { font-size: var(--text-sm); font-weight: 600; }

p { line-height: 1.7; }

.mono, code { font-family: var(--font-mono); }

.text-xs   { font-size: var(--text-xs); }
.text-sm   { font-size: var(--text-sm); }
.text-base { font-size: var(--text-base); }
.text-lg   { font-size: var(--text-lg); }

.text-muted    { color: var(--clr-text-muted); }
.text-secondary{ color: var(--clr-text-secondary); }
.text-primary  { color: var(--clr-primary); }
.text-accent   { color: var(--clr-accent); }
.text-error    { color: var(--clr-error); }
.text-warning  { color: var(--clr-warning); }

.font-headline { font-family: var(--font-headline); }
.font-mono     { font-family: var(--font-mono); }

.fw-400 { font-weight: 400; }
.fw-500 { font-weight: 500; }
.fw-600 { font-weight: 600; }
.fw-700 { font-weight: 700; }
.fw-800 { font-weight: 800; }

.uppercase { text-transform: uppercase; letter-spacing: 0.08em; }
.label-sm  {
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--clr-text-muted);
}

/* ---------- Layout Utilities ---------- */
.flex         { display: flex; }
.flex-col     { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.items-start  { align-items: flex-start; }
.justify-between { justify-content: space-between; }
.justify-center  { justify-content: center; }
.justify-end     { justify-content: flex-end; }
.gap-1  { gap: var(--sp-1); }
.gap-2  { gap: var(--sp-2); }
.gap-3  { gap: var(--sp-3); }
.gap-4  { gap: var(--sp-4); }
.gap-6  { gap: var(--sp-6); }
.gap-8  { gap: var(--sp-8); }
.flex-1 { flex: 1; }
.flex-wrap { flex-wrap: wrap; }
.shrink-0 { flex-shrink: 0; }

.w-full  { width: 100%; }
.h-full  { height: 100%; }
.min-h-0 { min-height: 0; }
.overflow-hidden { overflow: hidden; }
.overflow-auto   { overflow: auto; }
.overflow-y-auto { overflow-y: auto; }

.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: var(--sp-4); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--sp-4); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--sp-4); }

/* ---------- Spacing Utilities ---------- */
.p-2  { padding: var(--sp-2); }
.p-3  { padding: var(--sp-3); }
.p-4  { padding: var(--sp-4); }
.p-6  { padding: var(--sp-6); }
.p-8  { padding: var(--sp-8); }
.px-3 { padding-left: var(--sp-3); padding-right: var(--sp-3); }
.px-4 { padding-left: var(--sp-4); padding-right: var(--sp-4); }
.px-6 { padding-left: var(--sp-6); padding-right: var(--sp-6); }
.py-2 { padding-top: var(--sp-2); padding-bottom: var(--sp-2); }
.py-3 { padding-top: var(--sp-3); padding-bottom: var(--sp-3); }
.py-4 { padding-top: var(--sp-4); padding-bottom: var(--sp-4); }

.mt-1 { margin-top: var(--sp-1); }
.mt-2 { margin-top: var(--sp-2); }
.mt-3 { margin-top: var(--sp-3); }
.mt-4 { margin-top: var(--sp-4); }
.mt-6 { margin-top: var(--sp-6); }
.mt-8 { margin-top: var(--sp-8); }
.mb-2 { margin-bottom: var(--sp-2); }
.mb-3 { margin-bottom: var(--sp-3); }
.mb-4 { margin-bottom: var(--sp-4); }
.mb-6 { margin-bottom: var(--sp-6); }

/* ---------- Card ---------- */
.card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
}

.card-body { padding: var(--sp-4) var(--sp-5); }
.card-sm   { border-radius: var(--radius-sm); }
.card-lg   { border-radius: var(--radius-lg); }

/* ---------- Buttons ---------- */
button, .btn {
  font-family: var(--font-body);
  font-size: var(--text-base);
  font-weight: 600;
  cursor: pointer;
  border: 1.5px solid transparent;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-2);
  border-radius: var(--radius);
  padding: 8.5px 18px;
  transition: background var(--transition-fast), box-shadow var(--transition-fast), transform var(--transition-fast), opacity var(--transition-fast), border-color var(--transition-fast);
  text-decoration: none;
  line-height: 1.2;
  white-space: nowrap;
  position: relative;
}

button:focus-visible, .btn:focus-visible {
  outline: 2px solid var(--clr-primary);
  outline-offset: 2px;
}

button:active { transform: scale(0.98); }

.btn-primary {
  background: var(--clr-primary);
  color: #fff;
  border-color: var(--clr-primary);
}
.btn-primary:hover { background: var(--clr-primary-dark); border-color: var(--clr-primary-dark); }

.btn-secondary {
  background: var(--clr-secondary);
  color: #fff;
  border-color: var(--clr-secondary);
}
.btn-secondary:hover { background: #2d6389; border-color: #2d6389; }

.btn-accent {
  background: var(--clr-accent);
  color: #fff;
  border-color: var(--clr-accent);
}
.btn-accent:hover { background: #236b55; border-color: #236b55; }

.btn-danger {
  background: var(--clr-error);
  color: #fff;
  border-color: var(--clr-error);
}
.btn-danger:hover { background: #9c2f22; border-color: #9c2f22; }

.btn-ghost {
  background: transparent;
  color: var(--clr-text);
  border: 1.5px solid var(--clr-border);
}
.btn-ghost:hover { border-color: var(--clr-border-strong); background: var(--clr-bg); }

.btn-outline-primary {
  background: transparent;
  color: var(--clr-primary);
  border: 1.5px solid var(--clr-primary);
}
.btn-outline-primary:hover { background: var(--clr-primary-light); border-color: var(--clr-primary); }

.btn-xs { padding: 4px 8px; font-size: var(--text-xs); border-radius: var(--radius-sm); }
.btn-sm { padding: 6px 12px; font-size: var(--text-sm); border-radius: var(--radius-sm); }
.btn-lg { padding: 12px 24px; font-size: var(--text-md); border-radius: var(--radius-md); }
.btn-xl { padding: 16px 32px; font-size: var(--text-lg); border-radius: var(--radius-lg); }
.btn-block { width: 100%; }
.btn-icon { padding: 8px; border-radius: var(--radius); }

button:disabled, .btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none !important;
}

/* ---------- Form Controls ---------- */
label {
  display: block;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--clr-text-secondary);
  margin-bottom: var(--sp-1);
}

input[type="text"],
input[type="email"],
input[type="password"],
input[type="number"],
input[type="url"],
textarea,
select {
  font-family: var(--font-body);
  font-size: var(--text-base);
  color: var(--clr-text);
  background: var(--clr-surface);
  border: 1.5px solid var(--clr-border);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  width: 100%;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
  outline: none;
  line-height: 1.5;
}

input:focus, textarea:focus, select:focus {
  border-color: var(--clr-primary);
  box-shadow: 0 0 0 3px rgba(27,79,138,0.12);
}

input::placeholder, textarea::placeholder {
  color: var(--clr-text-disabled);
}

input:disabled, textarea:disabled, select:disabled {
  background: var(--clr-bg);
  color: var(--clr-text-muted);
  cursor: not-allowed;
}

.form-field { margin-bottom: var(--sp-4); }
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-4);
}

.input-group {
  display: flex;
  align-items: stretch;
}
.input-group input {
  border-radius: var(--radius-sm) 0 0 var(--radius-sm);
  flex: 1;
}
.input-group .btn {
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

/* Radio & Checkbox */
.option-label {
  display: flex;
  align-items: flex-start;
  gap: var(--sp-3);
  padding: var(--sp-3) var(--sp-4);
  border: 1.5px solid var(--clr-border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: border-color var(--transition-fast), background var(--transition-fast);
  font-size: var(--text-base);
  margin-bottom: var(--sp-2);
}

.option-label:hover { border-color: var(--clr-secondary); background: var(--clr-surface-alt); }

.option-label input[type="radio"],
.option-label input[type="checkbox"] {
  width: auto;
  margin-top: 2px;
  accent-color: var(--clr-primary);
  flex-shrink: 0;
}

.option-label input[type="radio"]:checked + *,
.option-label input[type="checkbox"]:checked + * {
  color: var(--clr-text);
}
.option-label input[type="radio"]:checked + * .text-muted,
.option-label input[type="checkbox"]:checked + * .text-muted {
  color: var(--clr-text-muted);
}

.option-label:has(input:checked) {
  border-color: var(--clr-primary);
  background: var(--clr-primary-light);
}

/* ---------- Chips / Badges ---------- */
.chip {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.04em;
  font-family: var(--font-mono);
  white-space: nowrap;
}

.chip-primary  { background: var(--clr-primary-light); color: var(--clr-primary); }
.chip-accent   { background: var(--clr-accent-light); color: var(--clr-accent); }
.chip-warning  { background: var(--clr-warning-light); color: #92400E; }
.chip-error    { background: var(--clr-error-light); color: var(--clr-error); }
.chip-success  { background: var(--clr-success-light); color: var(--clr-success); }
.chip-neutral  { background: var(--clr-surface-alt); color: var(--clr-text-muted); }
.chip-dark     { background: var(--clr-text); color: #fff; }

/* CEFR chips */
.chip-cefr { color: #fff; font-family: var(--font-mono); }
.chip-a0  { background: var(--cefr-a0); color: #1a2332; }
.chip-a1  { background: var(--cefr-a1); color: #fff; }
.chip-a1p { background: var(--cefr-a1p); color: #fff; }
.chip-a2  { background: var(--cefr-a2); color: #fff; }
.chip-a2p { background: var(--cefr-a2p); color: #fff; }
.chip-b1  { background: var(--cefr-b1); color: #fff; }
.chip-b1p { background: var(--cefr-b1p); color: #fff; }
.chip-b2  { background: var(--cefr-b2); color: #fff; }
.chip-b2p { background: var(--cefr-b2p); color: #fff; }
.chip-c1  { background: var(--cefr-c1); color: #fff; }

/* ---------- Divider ---------- */
.divider {
  border: none;
  border-top: 1px solid var(--clr-border);
  margin: var(--sp-4) 0;
}

/* ---------- Alert Banners ---------- */
.alert {
  display: flex;
  gap: var(--sp-3);
  padding: var(--sp-3) var(--sp-4);
  border-radius: var(--radius);
  font-size: var(--text-sm);
  line-height: 1.5;
}

.alert-warning {
  background: var(--clr-warning-light);
  border: 1px solid #FCD34D;
  color: #78350F;
}
.alert-error {
  background: var(--clr-error-light);
  border: 1px solid #FCA5A5;
  color: #7F1D1D;
}
.alert-success {
  background: var(--clr-success-light);
  border: 1px solid #6EE7B7;
  color: #064E3B;
}
.alert-info {
  background: var(--clr-primary-light);
  border: 1px solid #93C5FD;
  color: #1E3A5F;
}
.alert-icon { font-size: var(--text-lg); flex-shrink: 0; }

/* ---------- Progress Bar ---------- */
.progress-bar {
  height: 6px;
  background: var(--clr-border);
  border-radius: var(--radius-full);
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  background: var(--clr-primary);
  border-radius: var(--radius-full);
  transition: width var(--transition-slow);
}
.progress-fill.success { background: var(--clr-accent); }
.progress-fill.warning { background: var(--clr-warning); }

/* ---------- Toast ---------- */
#jcah-toast-container {
  position: fixed;
  bottom: 72px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: var(--sp-2);
  align-items: center;
  pointer-events: none;
}

.jcah-toast {
  background: var(--clr-text);
  color: #fff;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 500;
  box-shadow: var(--shadow-md);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity var(--transition), transform var(--transition);
  pointer-events: none;
  white-space: nowrap;
}

.jcah-toast.show {
  opacity: 1;
  transform: translateY(0);
}

/* ---------- Modal Overlay ---------- */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(26,35,50,0.5);
  backdrop-filter: blur(3px);
  z-index: 1000;
  display: none;
  align-items: center;
  justify-content: center;
  padding: var(--sp-6);
}

.modal-overlay.show { display: flex; }

.modal {
  background: var(--clr-surface);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-lg);
  max-width: 560px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--sp-5) var(--sp-6);
  border-bottom: 1px solid var(--clr-border);
}

.modal-body { padding: var(--sp-6); }
.modal-footer {
  padding: var(--sp-4) var(--sp-6);
  border-top: 1px solid var(--clr-border);
  display: flex;
  gap: var(--sp-3);
  justify-content: flex-end;
}

.modal-close {
  background: none;
  border: none;
  font-size: 20px;
  color: var(--clr-text-muted);
  cursor: pointer;
  padding: var(--sp-1);
  border-radius: var(--radius-sm);
  line-height: 1;
}
.modal-close:hover { color: var(--clr-text); background: var(--clr-bg); }

/* ---------- Scrollbar Styling ---------- */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--clr-border-strong); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--clr-text-muted); }

/* ---------- Matching question ---------- */
.matching-container { display: flex; flex-direction: column; gap: var(--sp-2); }
.matching-row {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
}
.matching-left {
  flex: 1;
  padding: var(--sp-2) var(--sp-3);
  background: var(--clr-surface-alt);
  border-radius: var(--radius-sm);
  font-size: var(--text-sm);
}
.matching-select {
  flex: 1;
  padding: 8px 12px;
  font-size: var(--text-sm);
}

/* ---------- Fill-in-blank input ---------- */
.fb-input {
  max-width: 360px;
  padding: 10px 14px;
  font-size: var(--text-base);
}

/* ---------- Responsive ---------- */
@media (max-width: 768px) {
  .form-row { grid-template-columns: 1fr; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
}

/* =====================================================================
   DARK THEME (Author Studio light/dark toggle)
   ===================================================================== */
[data-theme="dark"] {
  color-scheme: dark;

  /* Core palette — Studio Precision 2026 (Dark Mode) */
  --clr-primary:       #3b82f6;
  --clr-primary-dark:  #60a5fa;
  --clr-primary-light: rgba(59, 130, 246, 0.16);
  --clr-primary-glow:  rgba(59, 130, 246, 0.30);
  --clr-secondary:     #6bd8cb;
  --clr-accent:        #4edea3;
  --clr-accent-light:  rgba(78, 222, 163, 0.16);
  --clr-warning:       #fbbf24;
  --clr-warning-light: rgba(251, 191, 36, 0.16);
  --clr-error:         #f87171;
  --clr-error-light:   rgba(248, 113, 113, 0.16);
  --clr-success:       #4edea3;
  --clr-success-light: rgba(78, 222, 163, 0.16);

  /* Deep Studio Navy Surfaces (Stitch Studio Precision) */
  --clr-bg:            #0b1326;
  --clr-surface:       #131b2e;
  --clr-surface-low:   #0d1527;
  --clr-surface-container: #171f33;
  --clr-surface-high:  #222a3d;
  --clr-surface-highest: #2d3449;
  --clr-surface-alt:   #1a243b;
  --clr-border:        #283044;
  --clr-border-strong: #434655;
  --clr-border-subtle: #1c2538;
  --clr-text:          #f8fafc;
  --clr-text-secondary:#cbd5e1;
  --clr-text-muted:    #94a3b8;
  --clr-text-disabled: #64748b;

  /* Material / Wizard variables mapping (Dark) */
  --md-surface-container: var(--clr-surface-container);
  --md-surface-variant: var(--clr-surface-alt);
  --md-outline: var(--clr-border);
  --md-text-primary: var(--clr-text);
  --md-text-secondary: var(--clr-text-secondary);
  --md-primary: var(--clr-primary);
  --md-primary-container: rgba(59, 130, 246, 0.20);

  /* Question Type Distinct Accents (Dark) */
  --qtype-mc-bg:       rgba(59, 130, 246, 0.18);
  --qtype-mc-clr:      #93c5fd;
  --qtype-mc-border:   rgba(59, 130, 246, 0.40);

  --qtype-tf-bg:       rgba(20, 184, 166, 0.18);
  --qtype-tf-clr:      #5eead4;
  --qtype-tf-border:   rgba(20, 184, 166, 0.40);

  --qtype-fib-bg:      rgba(168, 85, 247, 0.18);
  --qtype-fib-clr:     #d8b4fe;
  --qtype-fib-border:  rgba(168, 85, 247, 0.40);

  --qtype-mr-bg:       rgba(245, 158, 11, 0.18);
  --qtype-mr-clr:      #fcd34d;
  --qtype-mr-border:   rgba(245, 158, 11, 0.40);

  --qtype-match-bg:    rgba(244, 63, 94, 0.18);
  --qtype-match-clr:   #fda4af;
  --qtype-match-border:rgba(244, 63, 94, 0.40);

  --shadow-xs: 0 1px 2px rgba(0,0,0,0.5);
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.55), 0 1px 2px rgba(0,0,0,0.45);
  --shadow:    0 4px 6px rgba(0,0,0,0.5), 0 2px 4px rgba(0,0,0,0.4);
  --shadow-md: 0 10px 15px rgba(0,0,0,0.6), 0 4px 6px rgba(0,0,0,0.45);
  --shadow-lg: 0 20px 25px rgba(0,0,0,0.65), 0 10px 10px rgba(0,0,0,0.5);
}

/* =====================================================================
   QUESTION TYPE BADGES & STUDIO PRECISION COMPONENTS
   ===================================================================== */
.badge-qtype, .qtype-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  user-select: none;
}
.badge-mc, .qtype-mc {
  background: var(--qtype-mc-bg);
  color: var(--qtype-mc-clr);
  border: 1px solid var(--qtype-mc-border);
}
.badge-tf, .qtype-tf {
  background: var(--qtype-tf-bg);
  color: var(--qtype-tf-clr);
  border: 1px solid var(--qtype-tf-border);
}
.badge-fib, .qtype-fib {
  background: var(--qtype-fib-bg);
  color: var(--qtype-fib-clr);
  border: 1px solid var(--qtype-fib-border);
}
.badge-mr, .qtype-mr {
  background: var(--qtype-mr-bg);
  color: var(--qtype-mr-clr);
  border: 1px solid var(--qtype-mr-border);
}
.badge-match, .qtype-match {
  background: var(--qtype-match-bg);
  color: var(--qtype-match-clr);
  border: 1px solid var(--qtype-match-border);
}

/* Studio Precision Segment Filter Tabs */
.qtype-filter-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding: 4px 0;
}
.qtype-filter-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  font-weight: 600;
  background: var(--clr-surface-container);
  color: var(--clr-text-secondary);
  border: 1px solid var(--clr-border);
  cursor: pointer;
  transition: all var(--transition-fast);
  white-space: nowrap;
}
.qtype-filter-btn:hover {
  background: var(--clr-surface-high);
  color: var(--clr-text);
  border-color: var(--clr-border-strong);
}
.qtype-filter-btn.active {
  background: var(--clr-primary);
  color: #ffffff;
  border-color: var(--clr-primary);
  box-shadow: 0 2px 8px var(--clr-primary-glow);
}
.qtype-filter-btn .filter-count-pill {
  padding: 1px 6px;
  border-radius: var(--radius-full);
  font-size: 10px;
  font-weight: 700;
  background: rgba(0, 0, 0, 0.15);
}
.qtype-filter-btn.active .filter-count-pill {
  background: rgba(255, 255, 255, 0.25);
  color: #ffffff;
}

/* Studio Question Workbench Card */
.studio-question-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  margin-bottom: var(--sp-4);
  overflow: hidden;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
  border-left: 4px solid var(--clr-border-strong);
}
.studio-question-card:hover {
  border-color: var(--clr-border-strong);
  box-shadow: var(--shadow);
}
.studio-question-card.active, .studio-question-card.border-accent-primary {
  border-left-color: var(--clr-primary);
}
.studio-question-card.border-accent-tf {
  border-left-color: var(--clr-secondary);
}
.studio-question-card.border-accent-fib {
  border-left-color: #9333ea;
}
.studio-question-card.border-accent-mr {
  border-left-color: var(--clr-warning);
}
.studio-question-card.border-accent-match {
  border-left-color: #e11d48;
}

.studio-card-header {
  padding: 10px 16px;
  background: var(--clr-surface-container);
  border-bottom: 1px solid var(--clr-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.studio-card-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.studio-card-footer {
  padding: 10px 16px;
  background: var(--clr-surface-low);
  border-top: 1px solid var(--clr-border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: var(--text-xs);
  color: var(--clr-text-muted);
}

/* =====================================================================
   CUSTOM INTERACTION FONT OVERRIDES
   Applied globally across Author Studio and Candidate Exam Runtime
   ===================================================================== */
[data-custom-font="true"],
[data-custom-font="true"] body,
[data-custom-font="true"] .studio-app-shell,
[data-custom-font="true"] .app-shell,
[data-custom-font="true"] .wizard-container,
[data-custom-font="true"] .exam-shell {
  font-family: var(--font-body) !important;
}

[data-custom-font="true"] h1,
[data-custom-font="true"] h2,
[data-custom-font="true"] h3,
[data-custom-font="true"] h4,
[data-custom-font="true"] h5,
[data-custom-font="true"] h6,
[data-custom-font="true"] .font-headline,
[data-custom-font="true"] .step-heading,
[data-custom-font="true"] .studio-nav-brand,
[data-custom-font="true"] .pipeline-card-title {
  font-family: var(--font-headline) !important;
}

[data-custom-font="true"] button,
[data-custom-font="true"] input:not([type="checkbox"]):not([type="radio"]),
[data-custom-font="true"] select,
[data-custom-font="true"] textarea,
[data-custom-font="true"] .btn,
[data-custom-font="true"] .ql-editor,
[data-custom-font="true"] .passage-box,
[data-custom-font="true"] .passage-card,
[data-custom-font="true"] .option-card,
[data-custom-font="true"] .stem-display,
[data-custom-font="true"] .rubric-display,
[data-custom-font="true"] .question-text,
[data-custom-font="true"] .option-label {
  font-family: var(--font-body) !important;
}

/* Ensure code and telemetry badges retain crisp monospace */
[data-custom-font="true"] code,
[data-custom-font="true"] pre,
[data-custom-font="true"] kbd,
[data-custom-font="true"] samp,
[data-custom-font="true"] .mono,
[data-custom-font="true"] .font-mono,
[data-custom-font="true"] .chip-cefr,
[data-custom-font="true"] .timer-badge,
[data-custom-font="true"] .exam-token-chip,
[data-custom-font="true"] .specimen-id-badge,
[data-custom-font="true"] .telemetry-pill {
  font-family: var(--font-mono) !important;
}

/* Inline code tags styling across light & dark themes */
code {
  font-family: var(--font-mono);
  font-size: 0.88em;
  padding: 1.5px 5px;
  border-radius: var(--radius-xs);
  background: var(--clr-surface-container);
  color: var(--clr-primary);
  border: 1px solid var(--clr-border);
}
[data-theme="dark"] code {
  background: rgba(255, 255, 255, 0.08);
  color: #93c5fd;
  border-color: rgba(255, 255, 255, 0.16);
}

